uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// User Parameters (Preserved from Previous Version)
uniform float u_speed;
uniform float u_fov;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_complexity; 
uniform float u_viscosity;
uniform float u_paper_texture;
uniform float u_metallic_shine;
uniform float u_bloom_brightness;
uniform float u_paint_thickness;
uniform float u_creaminess;
uniform float u_melting;
uniform float u_berry_intensity; 
uniform float u_wave_height;
uniform float u_orange_hue;
uniform float u_neon_saturation;
uniform float u_edge_glow;
uniform float u_transparency;
uniform float u_baby_blue_mix;

// Integrated Organic/Neural Parameters
uniform float u_wave_speed;   
uniform float u_organic_flow;  
uniform float u_smoothness;    
uniform float u_fluidity;      
uniform float u_neural_density;

out vec4 fragColor;

// --- UTILS ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Domain warping from the organic logic
vec2 domainWarp(vec2 p, float t) {
    float n1 = noise(p + t * 0.2);
    float n2 = noise(p + vec2(n1, n1) + t * 0.1);
    return p + vec2(cos(n2 * 6.28), sin(n2 * 6.28)) * u_fluidity * 0.2;
}

// Organic distortion helper
vec2 distort(vec2 p, float t) {
    p += 0.15 * cos(vec2(t + p.y * 1.5, t + p.x * 1.5) * u_organic_flow);
    p += 0.1 * sin(vec2(t * 1.2 + p.y * 3.0, t * 0.8 + p.x * 3.5));
    return p;
}

// Updated Palette for Pink, Purple, and Baby Blue
vec3 getNeonPalette(float t, float mask) {
    vec3 hotPink    = vec3(1.0, 0.1, 0.6) * u_berry_intensity * u_neon_saturation; 
    vec3 deepPurple = vec3(0.5, 0.0, 1.0) * u_berry_intensity * u_neon_saturation; 
    vec3 babyBlue   = vec3(0.5, 0.8, 1.0) * u_neon_saturation;

    float selector = sin(t * 1.5 + mask * 4.0) * 0.5 + 0.5;
    vec3 finalCol = mix(deepPurple, hotPink, smoothstep(0.1, 0.7, selector));
    finalCol = mix(finalCol, babyBlue, smoothstep(0.7, 1.0, selector) * u_baby_blue_mix);

    vec3 highlightShift = vec3(0.8, 0.3, 1.0) * u_neon_saturation;
    finalCol = mix(finalCol, highlightShift, (1.0 - selector) * u_orange_hue);

    return finalCol;
}

// Neural flow line logic mixed with neon colors
float getNeuralLine(vec2 uv, float id, float t) {
    float h = hash(vec2(id, 123.45));
    float speed = (h - 0.5) * 2.0 * u_wave_speed;
    float offset = h * 6.28;
    float curve = sin(uv.x * u_complexity + t * speed + offset) * 0.25 * u_organic_flow;
    float line = abs(uv.y - curve);
    float pulse = smoothstep(0.3, 0.7, sin(uv.x * 1.5 - t * 2.5 + offset));
    return (0.012 / max(line, 0.001)) * (0.4 + 0.6 * pulse);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv_orig = uv;

    // Zoom control
    uv *= (3.0 - u_fov); 

    float t = iTime * u_speed * 0.15;
    float neuralTime = iTime * u_wave_speed;

    // Apply Organic Domain Warping
    uv = domainWarp(uv, t);

    vec2 p = uv;
    float flow = 0.0;

    // Melt effect
    p.y -= t * u_melting * 0.25;

    // Fractal Folding with Organic influence
    float waveAmp = u_wave_height;
    for(float i = 1.0; i <= u_complexity; i++) {
        p.x += (waveAmp / i) * sin(i * 1.8 * p.y + t + u_viscosity * 4.0);
        p.y += (waveAmp / i) * cos(i * 1.8 * p.x + t + u_viscosity * 4.0);
        p *= rot(u_camera_dist * 0.04);
        flow += length(p - uv);
    }

    // Core Distance Field
    float d = length(sin(p * 0.9)) - 0.45;
    float mask = smoothstep(1.0 + u_paint_thickness * 0.5, -0.3, d);
    float edge = exp(-abs(d) * (10.0 - u_edge_glow)) * (u_glow_intensity + 0.5);

    // Base Neon Color
    vec3 baseCol = getNeonPalette(flow * 0.12 + t * 0.15, mask);
    vec3 finalCol = baseCol * mask;
    finalCol += baseCol * edge * 1.5; 

    // Neural Flow Overlay
    vec2 neuralUV = distort(uv * u_neural_density, neuralTime * 0.15);
    for(float j = 0.0; j < 3.0; j++) {
        float angle = j * 1.57 + noise(vec2(j, neuralTime * 0.1)) * 0.5;
        mat2 rotMat = rot(angle);
        vec2 np = rotMat * neuralUV + (noise(neuralUV * 0.5 + neuralTime * 0.1) - 0.5) * 0.3;

        float lineIntensity = getNeuralLine(np, j, neuralTime);
        vec3 neuralCol = getNeonPalette(neuralTime * 0.1 + j * 0.5, lineIntensity);
        finalCol += neuralCol * lineIntensity * (0.5 / max(u_smoothness, 0.1));
    }

    // Glossy Reflections
    vec3 n = normalize(vec3(dFdx(flow), dFdy(flow), 0.1 / (0.01 + u_wave_height))); 
    vec3 lightDir = normalize(vec3(sin(t * 0.3), 1.0, 1.5));
    float spec = pow(max(0.0, dot(n, lightDir)), 20.0) * u_metallic_shine;
    vec3 highlight = vec3(0.8, 0.9, 1.0);
    finalCol += spec * highlight * u_bloom_brightness;

    // Grain/Dust
    if (u_paper_texture > 0.0) {
        float grain = noise(gl_FragCoord.xy * 0.4 + t);
        float seedPattern = step(0.99 - u_paper_texture * 0.05, noise(p * 20.0 + flow));
        finalCol += seedPattern * mix(baseCol, highlight, 0.5) * 2.0;
    }

    // Transparency & Vignette
    float alpha = clamp(mask + edge * 0.8 + (length(finalCol) * 0.2), 0.0, 1.0) * u_transparency;
    float vignette = smoothstep(1.5, 0.3, length(uv_orig));
    finalCol *= vignette;

    finalCol = pow(finalCol, vec3(0.85)); 
    fragColor = vec4(finalCol, alpha);
}
